(function(){
  var $=function(id){return document.getElementById(id)};
  function camel(s){
    return s.split(/\s+/).filter(Boolean).map(function(x){
      return x.charAt(0).toUpperCase()+x.slice(1);
    }).join('');
  }
  function run(){
    var raw=$('src').value;
    // split on newlines and commas, but NOT on spaces, because a multi word
    // phrase should become one hashtag rather than three
    var parts=raw.split(/[\n,]+/).map(function(s){return s.trim()}).filter(Boolean);
    var fixes=0, seen={}, out=[];
    parts.forEach(function(p){
      var before=p;
      // a line can hold several hashtags already
      var chunks = /#/.test(p) ? p.split(/\s+/).filter(Boolean) : [p];
      chunks.forEach(function(c){
        var s=c.replace(/^#+/,'');                       // ## and stray hashes
        s=s.replace(/[^\p{L}\p{N}_ ]+/gu,' ');           // punctuation and emoji out
        s=s.replace(/\s+/g,' ').trim();
        if(!s) return;
        var styled = $('style').value==='camel' ? camel(s)
                   : $('style').value==='keep' ? s.replace(/\s+/g,'')
                   : s.toLowerCase().replace(/\s+/g,'');
        if(!styled) return;
        if(/^[0-9]+$/.test(styled)) { fixes++; return; }  // numbers alone are not hashtags
        var key=styled.toLowerCase();
        if($('dedupe').checked && seen[key]) { fixes++; return; }
        seen[key]=1;
        out.push(styled);
        if(('#'+styled)!==before.trim()) fixes++;
      });
    });
    if($('sortaz').checked) out.sort(function(a,b){return a.toLowerCase().localeCompare(b.toLowerCase())});
    var h=$('hash').checked?'#':'';
    var tagged=out.map(function(t){return h+t});
    var joined;
    var sep=$('sep').value;
    if(sep==='nl') joined=tagged.join('\n');
    else if(sep==='comma') joined=tagged.join(', ');
    else if(sep==='dotnl') joined='.\n.\n.\n.\n.\n'+tagged.join(' ');
    else joined=tagged.join(' ');
    $('out').textContent = tagged.length ? joined : 'Your clean hashtags appear here';
    $('nin').textContent=parts.length;
    $('nout').textContent=out.length;
    $('nfix').textContent=fixes;
    $('note').textContent = sep==='dotnl'
      ? 'The row of dots pushes the hashtags below the More link on Instagram, so the caption looks clean in the feed.'
      : 'Spaces inside a phrase are removed rather than split, so "home workout" becomes one hashtag and not two.';
    if(window.WT) WT.resize();
  }
  ['src','style','sep','dedupe','sortaz','hash'].forEach(function(id){
    $(id).addEventListener('input',run); $(id).addEventListener('change',run);
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('out').textContent);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy result'},1400);
  });
  $('clear').addEventListener('click',function(){ $('src').value=''; run(); });
  run();
})();
